#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <atomic>
static std::uint64_t clock_ns(){timespec t{};clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t);return std::uint64_t(t.tv_sec)*1000000000+std::uint64_t(t.tv_nsec);}
[[gnu::noinline]]static std::uint64_t kernel(const std::vector<std::uint64_t>& ns,int mode){std::uint64_t sum=0;for(auto n:ns){if(mode==0)sum+=MillerRabin(n,{2,325,9375,28178,450775,9780504,1795265022});if(mode==1)sum^=next_prime(n).value_or(0);if(mode==2)sum^=prev_prime(n).value_or(0);}return sum;}
int main(int argc,char**argv){const int mode=argc>1?std::atoi(argv[1]):0;std::mt19937_64 rng(412869);std::vector<std::uint64_t> ns;for(int i=0;i<4096;++i)ns.push_back((rng()|1));const auto t0=clock_ns();std::atomic_signal_fence(std::memory_order_seq_cst);const auto sum=kernel(ns,mode);std::atomic_signal_fence(std::memory_order_seq_cst);const auto t1=clock_ns();std::printf("%ju %ju\n",static_cast<std::uintmax_t>(t1-t0),static_cast<std::uintmax_t>(sum));}

