// SPDX-License-Identifier: CC0-1.0
// run_whitebox.pyがclass直後にpublic:を1行加えたテスト用コピーで内部演算を照合する。
#include SIRKIT_PRIMALITY_SOURCE
#include <boost/multiprecision/cpp_int.hpp>
#include <array>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <random>
#include <vector>
using Big=boost::multiprecision::cpp_int;using U=std::uint64_t;
static std::size_t checks=0,moduli=0,products=0,powers=0;
static void require_impl(bool ok,const char*expr,int line){++checks;if(!ok){std::fprintf(stderr,"line %d: %s\n",line,expr);std::abort();}}
#define require(x) require_impl(bool(x),#x,__LINE__)
static Big inverse(Big a,Big n){const Big mod=n;Big x=1,y=0;while(n!=0){const Big q=a/n;const Big next=a-q*n;a=n;n=next;const Big z=x-q*y;x=y;y=z;}require(a==1);x%=mod;if(x<0)x+=mod;return x;}
template<bool Relaxed>static void inspect(U n,std::mt19937_64&rng){
 ++moduli;reinsirk::detail::MillerRabin64<Relaxed> context(n);const Big mod=n,R=Big(1)<<64,ri=inverse(R%mod,mod);require(Big(context.one_)==R%mod);require(Big(context.normalize(context.r_squared_))==R*R%mod);require((context.odd_<<context.shifts_)==n-1);require(context.odd_&1);
 const U limit=Relaxed?n*2:n;std::vector<U> values{0,1,2,n-1};if constexpr(Relaxed){values.push_back(n);values.push_back(n*2-1);}for(unsigned i=0;i<40;++i)values.push_back(rng()%limit);
 for(auto a:values)for(auto b:values){++products;const U result=context.multiply(a,b);require(result<limit);require(Big(context.normalize(result))==(Big(a)*b*ri)%mod);}
 for(U exponent:std::array<U,8>{0,1,2,3,63,64,UINT64_C(0x8000000000000000),std::numeric_limits<U>::max()}){
  ++powers;const U a=rng()%n;const U mont=static_cast<U>(Big(a)*R%mod);const U result=context.normalize(context.power(mont,exponent));const Big expected=boost::multiprecision::powm(Big(a),Big(exponent),mod);require(Big(result)==expected*R%mod);
 }
}
int main(){std::mt19937_64 rng(991022);std::vector<U> ns{3,5,13,17,31,65537,4294967291ULL,4294967295ULL,4294967311ULL,4759123141ULL,(U{1}<<62)-3,(U{1}<<62)-1,(U{1}<<62)+1,(U{1}<<63)-1,(U{1}<<63)+1,std::numeric_limits<U>::max()-2,std::numeric_limits<U>::max()};for(unsigned i=0;i<100;++i)ns.push_back(rng()|3);for(auto n:ns){inspect<false>(n,rng);if(n<(U{1}<<62))inspect<true>(n,rng);}
#if !((defined(__GNUC__) || defined(__clang__)) && defined(__SIZEOF_INT128__) && !defined(SIRKIT_FORCE_STANDARD_ARITHMETIC))
 for(unsigned i=0;i<10000;++i){const U a=i? rng():std::numeric_limits<U>::max(),b=i?rng():std::numeric_limits<U>::max();const auto p=reinsirk::detail::MillerRabin64<false>::product(a,b);require((Big(p.high)<<64)+p.low==Big(a)*b);}
#endif
 std::printf("PASS checks=%zu moduli=%zu products=%zu powers=%zu\n",checks,moduli,products,powers);
}

